from collections import Counter, deque

def transform(grid):
    """Restore marked cells in large monochrome rectangular regions."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny,nx))
            if len(cells) >= 3:
                rs = [p[0] for p in cells]
                cs = [p[1] for p in cells]
                r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
                area = (r1-r0+1) * (c1-c0+1)
                if len(cells) / area >= 0.65:
                    boxes.append((r0, r1, c0, c1, color))
    out = [[background for _ in range(w)] for _ in range(h)]
    for r0, r1, c0, c1, color in boxes:
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                out[r][c] = color
    return out
